PRAGMA foreign_keys = ON;
BEGIN;
CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY CHECK(version=1), applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO schema_version(version) VALUES(1);
CREATE TABLE IF NOT EXISTS staff(staff_id TEXT PRIMARY KEY, display_name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','reviewer','coordinator','analyst')), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)));
CREATE TABLE IF NOT EXISTS patients(patient_id TEXT PRIMARY KEY, age_band TEXT NOT NULL CHECK(age_band IN ('18-29','30-44','45-59','60-74','75+','unknown')), contact_ref TEXT UNIQUE, sms_opt_in INTEGER NOT NULL DEFAULT 0 CHECK(sms_opt_in IN (0,1)), is_synthetic INTEGER NOT NULL DEFAULT 1 CHECK(is_synthetic=1), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(sms_opt_in=0 OR contact_ref IS NOT NULL));
CREATE TABLE IF NOT EXISTS appointments(appointment_id TEXT PRIMARY KEY, patient_id TEXT NOT NULL REFERENCES patients(patient_id), scheduled_at TEXT NOT NULL CHECK(datetime(scheduled_at) IS NOT NULL), department TEXT NOT NULL, appointment_type TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','attended','no_show','cancelled','rescheduled')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS surveys(survey_id TEXT PRIMARY KEY, appointment_id TEXT NOT NULL REFERENCES appointments(appointment_id), recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, attendance_confidence INTEGER CHECK(attendance_confidence BETWEEN 0 AND 10), transport_difficulty INTEGER CHECK(transport_difficulty IN (0,1)), financial_difficulty INTEGER CHECK(financial_difficulty IN (0,1)), accessibility_need INTEGER CHECK(accessibility_need IN (0,1)), timing_conflict INTEGER CHECK(timing_conflict IN (0,1)), language_support INTEGER CHECK(language_support IN (0,1)), caring_responsibility INTEGER CHECK(caring_responsibility IN (0,1)), support_consent INTEGER NOT NULL DEFAULT 0 CHECK(support_consent IN (0,1)));
CREATE TABLE IF NOT EXISTS model_registry(model_id TEXT PRIMARY KEY, model_kind TEXT NOT NULL CHECK(model_kind IN ('predictive','causal','nlp','placeholder')), version TEXT NOT NULL, artifact_path TEXT, validation_status TEXT NOT NULL DEFAULT 'unvalidated' CHECK(validation_status IN ('unvalidated','synthetic_validated','external_validated')), UNIQUE(model_kind,version));
CREATE TABLE IF NOT EXISTS predictions(prediction_id TEXT PRIMARY KEY, appointment_id TEXT NOT NULL REFERENCES appointments(appointment_id), model_id TEXT NOT NULL REFERENCES model_registry(model_id), predicted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, no_show_probability REAL NOT NULL CHECK(no_show_probability BETWEEN 0 AND 1), explanation_json TEXT CHECK(explanation_json IS NULL OR json_valid(explanation_json)), is_simulated INTEGER NOT NULL DEFAULT 1 CHECK(is_simulated=1));
CREATE TABLE IF NOT EXISTS barriers(barrier_id TEXT PRIMARY KEY, appointment_id TEXT NOT NULL REFERENCES appointments(appointment_id), category TEXT NOT NULL CHECK(category IN ('transport','financial','accessibility','timing','language','caring','anxiety','other')), source TEXT NOT NULL CHECK(source IN ('survey','chatbot','staff')), recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, confirmed INTEGER NOT NULL DEFAULT 0 CHECK(confirmed IN (0,1)));
CREATE TABLE IF NOT EXISTS interventions(intervention_id TEXT PRIMARY KEY, appointment_id TEXT NOT NULL REFERENCES appointments(appointment_id), kind TEXT NOT NULL CHECK(kind IN ('transport','reschedule','reminder','interpreter','accessibility','financial_support','staff_review')), rationale TEXT NOT NULL, estimated_benefit REAL CHECK(estimated_benefit BETWEEN -1 AND 1), evidence_status TEXT NOT NULL DEFAULT 'not_estimated' CHECK(evidence_status IN ('not_estimated','synthetic_estimate')), status TEXT NOT NULL DEFAULT 'proposed' CHECK(status IN ('proposed','approved','rejected','in_progress','completed','cancelled')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK((estimated_benefit IS NULL AND evidence_status='not_estimated') OR (estimated_benefit IS NOT NULL AND evidence_status='synthetic_estimate')));
CREATE TABLE IF NOT EXISTS intervention_decisions(decision_id TEXT PRIMARY KEY, intervention_id TEXT NOT NULL UNIQUE REFERENCES interventions(intervention_id), staff_id TEXT NOT NULL REFERENCES staff(staff_id), decision TEXT NOT NULL CHECK(decision IN ('approve','reject')), reason TEXT NOT NULL CHECK(length(trim(reason))>0), decided_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS communications(message_id TEXT PRIMARY KEY, appointment_id TEXT NOT NULL REFERENCES appointments(appointment_id), intervention_id TEXT REFERENCES interventions(intervention_id), channel TEXT NOT NULL CHECK(channel='sms'), template_key TEXT NOT NULL, dedupe_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'simulated' CHECK(status IN ('simulated','failed')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS transport_referrals(referral_id TEXT PRIMARY KEY, intervention_id TEXT NOT NULL UNIQUE REFERENCES interventions(intervention_id), eligibility_status TEXT NOT NULL CHECK(eligibility_status IN ('demo_eligible','demo_ineligible','review_required')), mobility_notes TEXT, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','submitted','cancelled','completed')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS transport_bookings(booking_id TEXT PRIMARY KEY, referral_id TEXT NOT NULL UNIQUE REFERENCES transport_referrals(referral_id), provider TEXT NOT NULL CHECK(provider='SIMULATED_PROVIDER'), pickup_at TEXT NOT NULL CHECK(datetime(pickup_at) IS NOT NULL), status TEXT NOT NULL DEFAULT 'simulated' CHECK(status IN ('simulated','cancelled','completed')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_events(event_id INTEGER PRIMARY KEY AUTOINCREMENT, actor_id TEXT REFERENCES staff(staff_id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, details_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(details_json)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_appointments_patient ON appointments(patient_id,scheduled_at);
CREATE INDEX IF NOT EXISTS idx_appointments_status ON appointments(status,scheduled_at);
CREATE INDEX IF NOT EXISTS idx_surveys_appointment ON surveys(appointment_id,recorded_at);
CREATE INDEX IF NOT EXISTS idx_predictions_appointment ON predictions(appointment_id,predicted_at);
CREATE INDEX IF NOT EXISTS idx_barriers_appointment ON barriers(appointment_id);
CREATE INDEX IF NOT EXISTS idx_interventions_appointment ON interventions(appointment_id,status);
CREATE INDEX IF NOT EXISTS idx_messages_appointment ON communications(appointment_id);
CREATE INDEX IF NOT EXISTS idx_audit_entity ON audit_events(entity_type,entity_id);
CREATE TRIGGER IF NOT EXISTS audit_no_update BEFORE UPDATE ON audit_events BEGIN SELECT RAISE(ABORT,'audit events are append-only'); END;
CREATE TRIGGER IF NOT EXISTS audit_no_delete BEFORE DELETE ON audit_events BEGIN SELECT RAISE(ABORT,'audit events are append-only'); END;
CREATE TRIGGER IF NOT EXISTS decision_guard BEFORE INSERT ON intervention_decisions BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM staff WHERE staff_id=NEW.staff_id AND active=1 AND role IN ('admin','reviewer')) THEN RAISE(ABORT,'active reviewer required') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM interventions WHERE intervention_id=NEW.intervention_id AND status='proposed') THEN RAISE(ABORT,'intervention must be proposed') END;
END;
CREATE TRIGGER IF NOT EXISTS decision_no_update BEFORE UPDATE ON intervention_decisions BEGIN SELECT RAISE(ABORT,'decisions immutable'); END;
CREATE TRIGGER IF NOT EXISTS decision_no_delete BEFORE DELETE ON intervention_decisions BEGIN SELECT RAISE(ABORT,'decisions immutable'); END;
CREATE TRIGGER IF NOT EXISTS intervention_insert_guard BEFORE INSERT ON interventions WHEN NEW.status<>'proposed' BEGIN SELECT RAISE(ABORT,'new intervention must be proposed'); END;
CREATE TRIGGER IF NOT EXISTS intervention_identity_guard BEFORE UPDATE OF appointment_id,kind ON interventions WHEN NEW.appointment_id<>OLD.appointment_id OR NEW.kind<>OLD.kind BEGIN SELECT RAISE(ABORT,'intervention identity immutable'); END;
CREATE TRIGGER IF NOT EXISTS intervention_transition BEFORE UPDATE OF status ON interventions WHEN NEW.status<>OLD.status BEGIN
 SELECT CASE WHEN NOT ((OLD.status='proposed' AND NEW.status IN ('approved','rejected','cancelled')) OR (OLD.status='approved' AND NEW.status IN ('in_progress','cancelled')) OR (OLD.status='in_progress' AND NEW.status IN ('completed','cancelled'))) THEN RAISE(ABORT,'invalid intervention transition') END;
 SELECT CASE WHEN NEW.status IN ('approved','in_progress','completed') AND NOT EXISTS(SELECT 1 FROM intervention_decisions WHERE intervention_id=NEW.intervention_id AND decision='approve') THEN RAISE(ABORT,'approval required') END;
 SELECT CASE WHEN NEW.status='rejected' AND NOT EXISTS(SELECT 1 FROM intervention_decisions WHERE intervention_id=NEW.intervention_id AND decision='reject') THEN RAISE(ABORT,'rejection decision required') END;
END;
CREATE TRIGGER IF NOT EXISTS decision_apply AFTER INSERT ON intervention_decisions BEGIN UPDATE interventions SET status=CASE NEW.decision WHEN 'approve' THEN 'approved' ELSE 'rejected' END WHERE intervention_id=NEW.intervention_id; END;
CREATE TRIGGER IF NOT EXISTS sms_guard BEFORE INSERT ON communications BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM appointments a JOIN patients p ON p.patient_id=a.patient_id WHERE a.appointment_id=NEW.appointment_id AND a.status='scheduled' AND p.sms_opt_in=1 AND p.contact_ref IS NOT NULL) THEN RAISE(ABORT,'scheduled appointment and SMS opt-in required') END;
 SELECT CASE WHEN NEW.intervention_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM interventions i JOIN intervention_decisions d ON d.intervention_id=i.intervention_id WHERE i.intervention_id=NEW.intervention_id AND i.appointment_id=NEW.appointment_id AND d.decision='approve' AND i.status IN ('approved','in_progress','completed')) THEN RAISE(ABORT,'matching approved intervention required') END;
END;
CREATE TRIGGER IF NOT EXISTS sms_no_update BEFORE UPDATE ON communications BEGIN SELECT RAISE(ABORT,'communication records immutable'); END;
CREATE TRIGGER IF NOT EXISTS referral_guard BEFORE INSERT ON transport_referrals BEGIN
 SELECT CASE WHEN NEW.status<>'pending' THEN RAISE(ABORT,'new referral must be pending') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM interventions i JOIN intervention_decisions d ON d.intervention_id=i.intervention_id JOIN appointments a ON a.appointment_id=i.appointment_id WHERE i.intervention_id=NEW.intervention_id AND i.kind='transport' AND i.status IN ('approved','in_progress') AND d.decision='approve' AND a.status='scheduled' AND EXISTS(SELECT 1 FROM surveys s WHERE s.appointment_id=a.appointment_id AND s.support_consent=1 AND s.rowid=(SELECT s2.rowid FROM surveys s2 WHERE s2.appointment_id=a.appointment_id ORDER BY s2.recorded_at DESC,s2.rowid DESC LIMIT 1))) THEN RAISE(ABORT,'approved transport intervention and latest support consent required') END;
END;
CREATE TRIGGER IF NOT EXISTS referral_identity_guard BEFORE UPDATE OF intervention_id ON transport_referrals WHEN NEW.intervention_id<>OLD.intervention_id BEGIN SELECT RAISE(ABORT,'referral identity immutable'); END;
CREATE TRIGGER IF NOT EXISTS booking_guard BEFORE INSERT ON transport_bookings BEGIN
 SELECT CASE WHEN NEW.status<>'simulated' THEN RAISE(ABORT,'new booking must be simulated') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM transport_referrals r JOIN interventions i ON i.intervention_id=r.intervention_id JOIN intervention_decisions d ON d.intervention_id=i.intervention_id JOIN appointments a ON a.appointment_id=i.appointment_id WHERE r.referral_id=NEW.referral_id AND r.eligibility_status='demo_eligible' AND r.status='pending' AND i.status IN ('approved','in_progress') AND d.decision='approve' AND a.status='scheduled' AND datetime(NEW.pickup_at)<datetime(a.scheduled_at) AND EXISTS(SELECT 1 FROM surveys s WHERE s.appointment_id=a.appointment_id AND s.support_consent=1 AND s.rowid=(SELECT s2.rowid FROM surveys s2 WHERE s2.appointment_id=a.appointment_id ORDER BY s2.recorded_at DESC,s2.rowid DESC LIMIT 1))) THEN RAISE(ABORT,'eligible pending referral, approval, current consent and pickup before appointment required') END;
END;
CREATE TRIGGER IF NOT EXISTS booking_identity_guard BEFORE UPDATE OF referral_id,provider,pickup_at ON transport_bookings WHEN NEW.referral_id<>OLD.referral_id OR NEW.provider<>OLD.provider OR NEW.pickup_at<>OLD.pickup_at BEGIN SELECT RAISE(ABORT,'booking identity immutable'); END;
CREATE VIEW IF NOT EXISTS appointment_overview AS SELECT a.appointment_id,a.patient_id,a.scheduled_at,a.department,a.status,p.sms_opt_in,(SELECT no_show_probability FROM predictions pr WHERE pr.appointment_id=a.appointment_id ORDER BY predicted_at DESC,rowid DESC LIMIT 1) AS latest_risk FROM appointments a JOIN patients p ON p.patient_id=a.patient_id;
COMMIT;
